import assert from "node:assert/strict";
import { test } from "node:test";
import { serializeAuditEntry } from "../src/audit.ts";

test("a start entry names the plan", () => {
  const entry = serializeAuditEntry({
    type: "subscription_started",
    subscriptionId: "sub_1",
    occurredAt: "2025-01-05T09:00:00Z",
    plan: "pro",
  });
  assert.equal(entry, "2025-01-05T09:00:00Z sub_1 subscription_started plan=pro");
});

test("a plan change entry names both plans", () => {
  const entry = serializeAuditEntry({
    type: "plan_changed",
    subscriptionId: "sub_1",
    occurredAt: "2025-02-01T00:00:00Z",
    from: "basic",
    to: "enterprise",
  });
  assert.equal(entry, "2025-02-01T00:00:00Z sub_1 plan_changed from=basic to=enterprise");
});

test("a recovery entry has no details", () => {
  const entry = serializeAuditEntry({
    type: "payment_recovered",
    subscriptionId: "sub_1",
    occurredAt: "2025-02-06T00:00:00Z",
  });
  assert.equal(entry, "2025-02-06T00:00:00Z sub_1 payment_recovered");
});

test("a cancellation entry quotes the reason", () => {
  const entry = serializeAuditEntry({
    type: "subscription_canceled",
    subscriptionId: "sub_1",
    occurredAt: "2025-03-01T00:00:00Z",
    reason: 'said "too expensive"',
  });
  assert.equal(entry, '2025-03-01T00:00:00Z sub_1 subscription_canceled reason="said \\"too expensive\\""');
});
=== test/notifier.test.ts
import assert from "node:assert/strict";
import { test } from "node:test";
import { notificationsFor } from "../src/notifier.ts";

test("a new subscription gets a welcome email", () => {
  const notifications = notificationsFor({
    type: "subscription_started",
    subscriptionId: "sub_1",
    occurredAt: "2025-01-05T09:00:00Z",
    plan: "pro",
  });
  assert.deepEqual(notifications, [{ audience: "customer", template: "welcome", data: { plan: "pro" } }]);
});

test("a failed payment tells the customer, and from the third attempt the billing team too", () => {
  const event = { type: "payment_failed", subscriptionId: "sub_1", occurredAt: "2025-02-05T00:00:00Z" } as const;
  assert.deepEqual(notificationsFor({ ...event, attempt: 2 }), [
    { audience: "customer", template: "payment-failed", data: { attempt: "2" } },
  ]);
  assert.deepEqual(notificationsFor({ ...event, attempt: 3 }), [
    { audience: "customer", template: "payment-failed", data: { attempt: "3" } },
    { audience: "billing-team", template: "payment-escalation", data: { attempt: "3" } },
  ]);
});

test("a recovery sends nothing", () => {
  const notifications = notificationsFor({
    type: "payment_recovered",
    subscriptionId: "sub_1",
    occurredAt: "2025-02-06T00:00:00Z",
  });
  assert.deepEqual(notifications, []);
});

test("a cancellation confirms to the customer with the reason", () => {
  const notifications = notificationsFor({
    type: "subscription_canceled",
    subscriptionId: "sub_1",
    occurredAt: "2025-03-01T00:00:00Z",
    reason: "too expensive",
  });
  assert.deepEqual(notifications, [
    { audience: "customer", template: "subscription-canceled", data: { reason: "too expensive" } },
  ]);
});
=== test/subscription.test.ts
import assert from "node:assert/strict";
import { test } from "node:test";
import type { SubscriptionEvent } from "../src/events.ts";
import { reduceSubscription, replay } from "../src/subscription.ts";

const started: SubscriptionEvent = {
  type: "subscription_started",
  subscriptionId: "sub_1",
  occurredAt: "2025-01-05T09:00:00Z",
  plan: "basic",
};

test("a started subscription is active on its plan", () => {
  const state = replay([started]);
  assert.equal(state.id, "sub_1");
  assert.equal(state.plan, "basic");
  assert.equal(state.status, "active");
  assert.equal(state.startedAt, "2025-01-05T09:00:00Z");
  assert.equal(state.canceledAt, null);
});

test("a plan change switches the plan", () => {
  const state = replay([
    started,
    { type: "plan_changed", subscriptionId: "sub_1", occurredAt: "2025-02-01T00:00:00Z", from: "basic", to: "pro" },
  ]);
  assert.equal(state.plan, "pro");
});

test("a failed payment makes the subscription past due and a recovery makes it active again", () => {
  const failed: SubscriptionEvent = {
    type: "payment_failed",
    subscriptionId: "sub_1",
    occurredAt: "2025-02-05T00:00:00Z",
    attempt: 2,
  };
  const pastDue = reduceSubscription(replay([started]), failed);
  assert.equal(pastDue.status, "past_due");
  assert.equal(pastDue.failedAttempts, 2);

  const recovered = reduceSubscription(pastDue, {
    type: "payment_recovered",
    subscriptionId: "sub_1",
    occurredAt: "2025-02-06T00:00:00Z",
  });
  assert.equal(recovered.status, "active");
  assert.equal(recovered.failedAttempts, 0);
});

test("cancelling records when it happened and a canceled subscription stays canceled", () => {
  const canceled = replay([
    started,
    { type: "subscription_canceled", subscriptionId: "sub_1", occurredAt: "2025-03-01T00:00:00Z", reason: "too expensive" },
  ]);
  assert.equal(canceled.status, "canceled");
  assert.equal(canceled.canceledAt, "2025-03-01T00:00:00Z");

  const afterFailure = reduceSubscription(canceled, {
    type: "payment_failed",
    subscriptionId: "sub_1",
    occurredAt: "2025-03-02T00:00:00Z",
    attempt: 1,
  });
  assert.equal(afterFailure, canceled);
});

test("a history that does not begin with the start is rejected", () => {
  assert.throws(() => replay([]), /starts with subscription_started/);
});
