export type Plan = "basic" | "pro" | "enterprise";

interface EventBase {
  subscriptionId: string;
  /** When it happened, as an ISO 8601 timestamp in UTC. */
  occurredAt: string;
}

export interface SubscriptionStarted extends EventBase {
  type: "subscription_started";
  plan: Plan;
}

export interface PlanChanged extends EventBase {
  type: "plan_changed";
  from: Plan;
  to: Plan;
}

export interface PaymentFailed extends EventBase {
  type: "payment_failed";
  /** 1 for the first failed charge, 2 for the retry after it, and so on. */
  attempt: number;
}

export interface PaymentRecovered extends EventBase {
  type: "payment_recovered";
}

export interface SubscriptionCanceled extends EventBase {
  type: "subscription_canceled";
  reason: string;
}

export type SubscriptionEvent =
  | SubscriptionStarted
  | PlanChanged
  | PaymentFailed
  | PaymentRecovered
  | SubscriptionCanceled;

import { assertNever } from "./assert-never.ts";
import type { SubscriptionEvent } from "./events.ts";

/** One line for the audit log: timestamp, subscription id, event type, then the event's details. */
export function serializeAuditEntry(event: SubscriptionEvent): string {
  const entry = `${event.occurredAt} ${event.subscriptionId} ${event.type}`;
  const details = auditDetails(event);
  return details === "" ? entry : `${entry} ${details}`;
}

function auditDetails(event: SubscriptionEvent): string {
  switch (event.type) {
    case "subscription_started":
      return `plan=${event.plan}`;
    case "plan_changed":
      return `from=${event.from} to=${event.to}`;
    case "payment_failed":
      return `attempt=${event.attempt}`;
    case "payment_recovered":
      return "";
    case "subscription_canceled":
      return `reason=${JSON.stringify(event.reason)}`;
    default:
      return assertNever(event);
  }
}

